def camper_form_data(camper):
    '''A camper as the form sent it (RegisterView.deserialize_camper in reverse).'''
    data = dict(camper.attributes or {})
    if camper.lodging_requested_id is not None:
        data['lodging'] = {
            'lodging_requested': {'id': camper.lodging_requested_id},
            'lodging_shared': camper.lodging_shared,
            'lodging_shared_with': camper.lodging_shared_with,
            'lodging_comments': camper.lodging_comments,
        }
    return data


def incomplete_registrations_into_drafts(apps, schema_editor):
    '''
    An incomplete registration is now a submitted draft under the same uuid, so a
    browser partway through paying goes on as if nothing changed (SPEC DR-140).
    One with an invoice, payment, charge or override, or already deleted, holds
    more than a draft can, and stays as it is.
    '''
    Camper = apps.get_model('camphoric', 'Camper')
    CustomCharge = apps.get_model('camphoric', 'CustomCharge')
    Invoice = apps.get_model('camphoric', 'Invoice')
    Payment = apps.get_model('camphoric', 'Payment')
    PricingOverride = apps.get_model('camphoric', 'PricingOverride')
    Registration = apps.get_model('camphoric', 'Registration')
    RegistrationDraft = apps.get_model('camphoric', 'RegistrationDraft')

    def has(model, path='registration'):
        return Exists(model._base_manager.filter(**{path: OuterRef('pk')}))

    # The plain manager, as a historical model's is: every row.
    incomplete = Registration._base_manager.filter(
        completed=False, deleted_at__isnull=True,
    ).exclude(has(Invoice)).exclude(has(Payment)).exclude(has(PricingOverride)).exclude(
        has(CustomCharge, 'camper__registration'))
    for registration in incomplete:
        campers = Camper._base_manager.filter(
            registration=registration, deleted_at__isnull=True).order_by('sequence', 'id')
        RegistrationDraft.objects.create(
            uuid=registration.uuid,
            event_id=registration.event_id,
            invitation_id=registration.started_with_invitation_id,
            registration_type_id=registration.registration_type_id,
            promo_code_id=registration.promo_code_id,
            registrant_email=registration.registrant_email,
            form_data={
                **(registration.attributes or {}),
                'registrant_email': registration.registrant_email,
                'campers': [camper_form_data(camper) for camper in campers],
            },
            server_pricing_results=registration.server_pricing_results,
            client_reported_pricing=registration.client_reported_pricing,
            submitted_at=registration.created_at,
            created_at=registration.created_at,
            last_activity_at=registration.updated_at,
        )
        registration.delete()


def drafts_into_registrations(apps, schema_editor):
    '''
    Back again: a submitted draft is an incomplete registration, under the same uuid.
    One still being filled in was never saved on the server, so it goes.
    '''
    Camper = apps.get_model('camphoric', 'Camper')
    Lodging = apps.get_model('camphoric', 'Lodging')
    Registration = apps.get_model('camphoric', 'Registration')
    RegistrationDraft = apps.get_model('camphoric', 'RegistrationDraft')

    lodgings = set(Lodging._base_manager.values_list('id', flat=True))
    for draft in RegistrationDraft.objects.filter(submitted_at__isnull=False):
        # bulk_create: these are records going back as they were, not saves to price.
        [registration] = Registration._base_manager.bulk_create([Registration(
            uuid=draft.uuid,
            event_id=draft.event_id,
            registration_type_id=draft.registration_type_id,
            promo_code_id=draft.promo_code_id,
            started_with_invitation_id=draft.invitation_id,
            attributes={key: value for key, value in draft.form_data.items()
                        if key not in ('campers', 'registrant_email')},
            registrant_email=draft.registrant_email,
            server_pricing_results=draft.server_pricing_results,
            client_reported_pricing=draft.client_reported_pricing,
        )])
        Registration._base_manager.filter(pk=registration.pk).update(
            created_at=draft.submitted_at, updated_at=draft.last_activity_at)
        priced = (draft.server_pricing_results or {}).get('campers') or []
        campers = []
        for sequence, data in enumerate(draft.form_data.get('campers') or []):
            attributes = {key: value for key, value in data.items() if key != 'lodging'}
            lodging = data.get('lodging') or {}
            requested = (lodging.get('lodging_requested') or {}).get('id')
            requested = requested if requested in lodgings else None
            campers.append(Camper(
                registration_id=registration.pk,
                sequence=sequence,
                attributes=attributes,
                lodging_id=requested,
                lodging_requested_id=requested,
                lodging_shared=lodging.get('lodging_shared', False),
                lodging_shared_with=lodging.get('lodging_shared_with', ''),
                lodging_comments=lodging.get('lodging_comments', ''),
                server_pricing_results=priced[sequence] if sequence < len(priced) else None,
            ))
        Camper._base_manager.bulk_create(campers)


